create table public.notification_templates(id uuid primary key default gen_random_uuid(),template_key text not null,channel text not null check(channel in ('in_app','email','whatsapp','sms')),language text not null check(language in ('en','hi')),subject_template text,body_template text not null,action_label text,required_variables text[] not null default '{}',version integer not null,status text not null default 'draft' check(status in ('draft','review','approved','retired')),approved_by uuid references auth.users(id),created_at timestamptz not null default now(),unique(template_key,channel,language,version));
create table public.notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,category text not null check(category in ('account','learning','evidence','interview','application','opportunity','organization','security')),priority text not null default 'normal' check(priority in ('low','normal','high','critical')),title text not null,body text not null,action_url text,action_label text,dedupe_key text,read_at timestamptz,archived_at timestamptz,expires_at timestamptz,created_at timestamptz not null default now(),unique(user_id,dedupe_key));
create table public.notification_deliveries(id uuid primary key default gen_random_uuid(),notification_id uuid not null references public.notifications(id) on delete cascade,channel text not null check(channel in ('in_app','email','whatsapp','sms')),template_id uuid references public.notification_templates(id),status text not null default 'queued' check(status in ('queued','deferred_quiet_hours','sent','delivered','failed','suppressed','unsubscribed')),provider_message_id text,error_code text,attempt_count smallint not null default 0,scheduled_at timestamptz,sent_at timestamptz,delivered_at timestamptz,created_at timestamptz not null default now());
create table public.communication_opt_ins(user_id uuid not null references auth.users(id) on delete cascade,channel text not null check(channel in ('whatsapp','sms')),destination_hash text not null,verified_at timestamptz,consented_at timestamptz not null,policy_version text not null,revoked_at timestamptz,primary key(user_id,channel));
alter table public.notification_templates enable row level security;alter table public.notifications enable row level security;alter table public.notification_deliveries enable row level security;alter table public.communication_opt_ins enable row level security;
create policy "users read notifications" on public.notifications for select using(user_id=auth.uid());create policy "users update notifications" on public.notifications for update using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "users read delivery status" on public.notification_deliveries for select using(exists(select 1 from public.notifications n where n.id=notification_id and n.user_id=auth.uid()));
create policy "users manage communication opt ins" on public.communication_opt_ins for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "staff manage notification templates" on public.notification_templates for all using(public.is_platform_staff()) with check(public.is_platform_staff());
create index notifications_inbox_idx on public.notifications(user_id,read_at,created_at desc) where archived_at is null;create index deliveries_queue_idx on public.notification_deliveries(status,scheduled_at);create index templates_active_idx on public.notification_templates(template_key,channel,language,status);
